<script setup lang="ts">
import { computed } from 'vue'
import { Bookmark, ChevronRight } from 'lucide-vue-next'
import { maintenanceDuration, maintenanceListSummary, maintenanceTimeBasis, type MaintenanceListRow } from './disclosureMaintenance'
import type { GridDisclosureCategory, GridDisclosureEvent } from './types'

const props = withDefaults(defineProps<{ rows: MaintenanceListRow[]; selectedId?: string | null; generic?: boolean }>(), { generic: false })
const emit = defineEmits<{ select: [event: GridDisclosureEvent] }>()
const items = computed(() => props.rows.map(row => ({ ...row, duration: maintenanceDuration(row.event), basis: maintenanceTimeBasis(row.event), listSummary: maintenanceListSummary(row.event) })))
const categoryLabels: Record<GridDisclosureCategory, string> = { maintenance: '检修计划', outage: '非计划停运', intervention: '人工干预', congestion: '断面阻塞', constraint: '输电约束' }
</script>

<template>
  <div class="maintenance-list" :data-testid="generic ? 'disclosure-list' : 'maintenance-list'">
    <div class="column-head" aria-hidden="true"><span>对象 / 摘要</span><span>类别 / 时间口径</span><span>{{ generic ? '生效 / 结束时间' : '停电 / 复电时间' }}</span><span>已知总时长</span></div>
    <p v-if="!items.length" class="empty" role="status">{{ generic ? '没有符合当前筛选条件的披露记录。' : '没有符合当前筛选条件的检修停运记录。' }}</p>
    <ul v-else :aria-label="generic ? '披露记录列表' : '检修停运记录列表'">
      <li v-for="item in items" :key="item.event.eventId" :data-event-id="item.event.eventId" :class="{ selected: selectedId === item.event.eventId }">
        <div class="object-column"><button type="button" class="open-event" :aria-label="`查看${item.event.title}详情`" :aria-pressed="selectedId === item.event.eventId" @click="emit('select', item.event)"><strong>{{ item.event.title }}</strong><ChevronRight :size="15" /></button><p class="reason">{{ item.listSummary || '摘要未提供' }}</p><div class="object-meta"><span>{{ item.event.spatialBinding.label }}</span><span>业务日期 {{ item.event.businessDate || '未提供' }}</span><span :class="['favorite', { watched: item.event.personalFavorite }]" :aria-label="item.event.personalFavorite ? '已加入个人收藏' : '未加入个人收藏'"><Bookmark :size="12" :fill="item.event.personalFavorite ? 'currentColor' : 'none'" />{{ item.event.personalFavorite ? '已收藏' : '未收藏' }}</span></div></div>
        <div class="category-column"><span class="category">{{ categoryLabels[item.event.category] }}</span><span class="basis" :class="item.event.timeQuality?.intervalBasis">{{ item.basis }}</span></div>
        <dl class="timing-column"><div><dt>{{ item.timing.startLabel }}</dt><dd>{{ item.timing.start }}</dd></div><div><dt>{{ item.timing.endLabel }}</dt><dd>{{ item.timing.end }}</dd></div><div v-if="item.timing.note && item.duration.status !== 'known'" class="timing-note"><dt>时间说明</dt><dd>{{ item.timing.note }}</dd></div></dl>
        <div class="duration-column"><span class="mobile-label">已知总时长</span><strong :class="{ warning: item.duration.status === 'invalid' }">{{ item.duration.label }}</strong><small v-if="item.duration.status === 'known'">完整{{ item.event.timeQuality?.intervalBasis === 'planned' ? '计划' : item.event.timeQuality?.intervalBasis === 'actual' ? '实际' : '来源' }}区间</small><small v-else>起止时间未确认完整</small></div>
      </li>
    </ul>
  </div>
</template>

<style scoped>
.maintenance-list{min-width:0;color:var(--text)}.column-head,.maintenance-list li{display:grid;grid-template-columns:minmax(180px,1.55fr) minmax(95px,.7fr) minmax(205px,1.2fr) minmax(90px,.6fr);gap:14px;align-items:start;padding:12px 16px}.column-head{background:var(--panel-sub);border-bottom:1px solid var(--line);font-size:var(--font-xs);color:var(--muted)}ul{list-style:none;padding:0;margin:0}.maintenance-list li{border-bottom:1px solid var(--line-soft);background:var(--panel);min-width:0}.maintenance-list li:last-child{border-bottom:0}.maintenance-list li.selected{box-shadow:inset 3px 0 var(--primary);background:var(--primary-tint)}.object-column,.category-column,.timing-column,.duration-column{min-width:0}.open-event{display:flex;align-items:flex-start;justify-content:space-between;gap:6px;text-align:left;width:100%;padding:0;border:0;background:transparent;color:var(--text);font:inherit;cursor:pointer}.open-event strong{font-size:var(--font-sm);font-weight:600;line-height:1.6;overflow-wrap:anywhere}.open-event svg{flex-shrink:0;margin-top:3px;color:var(--muted)}.open-event:hover{color:var(--primary)}.open-event:focus-visible{outline:2px solid var(--primary);outline-offset:3px;border-radius:3px}.reason{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;font-size:var(--font-xs);color:var(--text-soft);line-height:1.65;margin:6px 0;white-space:pre-wrap;overflow-wrap:anywhere}.object-meta{display:flex;gap:8px 12px;flex-wrap:wrap;color:var(--muted);font-size:var(--font-xs);line-height:1.6}.favorite{display:inline-flex;align-items:center;gap:3px}.favorite.watched{color:var(--primary)}.category-column{display:flex;flex-wrap:wrap;align-content:start;gap:6px}.category,.basis{font-size:var(--font-xs);border-radius:4px;padding:4px 6px;line-height:1.4;background:var(--panel-sub);color:var(--text-soft)}.basis.actual{background:var(--primary-tint);color:var(--primary)}.basis.planned{background:var(--warning-tint);color:var(--warning)}.timing-column{margin:0;display:grid;gap:8px}.timing-column>div{display:grid;gap:3px}.timing-column dt{font-size:var(--font-xs);color:var(--muted)}.timing-column dd{margin:0;font-size:var(--font-xs);line-height:1.5;color:var(--text-body);overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.timing-note{font-size:var(--font-xs);line-height:1.5;color:var(--muted);margin:0}.duration-column{display:grid;gap:6px;line-height:1.6}.duration-column strong{font-size:var(--font-sm);font-weight:600;overflow-wrap:anywhere}.duration-column small{color:var(--muted);font-size:var(--font-xs)}.duration-column .warning{color:var(--warning)}.mobile-label{display:none;font-size:var(--font-xs);color:var(--muted)}.empty{padding:28px 16px;text-align:center;font-size:var(--font-sm);color:var(--muted)}@media(max-width:1350px){.column-head,.maintenance-list li{grid-template-columns:minmax(150px,1.4fr) minmax(80px,.6fr) minmax(180px,1fr) minmax(75px,.6fr);gap:10px;padding:12px}}@media(max-width:1100px){.column-head{display:none}.maintenance-list li{display:grid;grid-template-columns:minmax(0,1fr);gap:10px;margin:10px 12px;border:1px solid var(--line);border-radius:7px;padding:12px}.maintenance-list li:last-child{border-bottom:1px solid var(--line)}.category-column{grid-row:1}.timing-column{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 14px}.timing-note{grid-column:1/-1}.duration-column{display:flex;flex-wrap:wrap;align-items:baseline;gap:7px 10px}.mobile-label{display:inline}.duration-column strong{font-size:var(--font-sm)}}@media(max-width:420px){.timing-column{grid-template-columns:minmax(0,1fr)}.maintenance-list li{margin:8px;padding:10px}.object-meta{gap:5px 8px}}
